fig, ax = style.figure(height_ratio=0.95)
ax.set_xlim(1940.9, 2020.3)
ax.set_ylim(-0.8, 20.5)

# Light Gaussian smoothing mimics the original kernel-density curves; sigma is in rate units.
SIGMA = {1970: 0.3, 1980: 0.4, 2010: 0.07, 2020: 0.10}


def smooth_profile(y, w, sigma):
    """Resample the digitised outline on a fine grid and smooth the half-widths.

    The first and last samples are the zero-width anchors of the digitisation, so they
    are dropped: the ridge then ends in a flat cut instead of a hook.
    """
    y = np.asarray(y)[1:-1][::-1]
    w = np.asarray(w)[1:-1][::-1]
    grid = np.arange(y[0], y[-1] + 1e-9, 0.01)
    return grid, gaussian_filter1d(np.interp(grid, y, w), sigma / 0.01, mode="nearest")


for decade, y, w in RIDGES:
    yy, ww = smooth_profile(y, w, SIGMA.get(decade, 0.16))
    x = decade - ww
    ax.fill_betweenx(yy, x, decade, facecolor=style.BLUE, edgecolor="none", zorder=3)
    ax.plot(x, yy, color=style.DARK, lw=0.8, solid_joinstyle="round", zorder=4)
    ax.plot([decade, decade], [-0.8, 20.5], color=style.LIGHT, lw=0.8, zorder=1)

ax.axhline(0, color=style.BLUE, lw=1.2, zorder=2)
for side in ("bottom", "left"):
    ax.spines[side].set_visible(side == "left")
ax.spines["left"].set_color(style.BLUE)
ax.spines["left"].set_linewidth(1.2)
ax.spines["left"].set_bounds(0, 20.5)

ax.set_yticks(np.arange(0, 20.1, 2.5))
ax.set_yticklabels([f"{v:.1f}" for v in np.arange(0, 20.1, 2.5)])
ax.set_xticks([r[0] for r in RIDGES])
ax.tick_params(axis="x", length=0, pad=4, labelrotation=90)
ax.tick_params(axis="y", length=0)

style.save(fig, OUT)
